<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $errors = get_transient( 'nekoko_registration_errors' ); $values = get_transient( 'nekoko_registration_values' ); $success = get_transient( 'nekoko_registration_success' ); delete_transient( 'nekoko_registration_errors' ); delete_transient( 'nekoko_registration_values' ); delete_transient( 'nekoko_registration_success' ); ?>
<form class="nekoko-form" method="post" action=""><h2>Registracija</h2><?php if ( $success ) { echo nekoko_core_form_notice( $success ); } if ( $errors instanceof WP_Error ) { echo nekoko_core_form_errors( $errors ); } ?><?php wp_nonce_field( 'nekoko_registration' ); ?><input type="hidden" name="nekoko_registration" value="1"><p class="nekoko-form__honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></p>
	<p><label for="nekoko-first">Ime *</label><input id="nekoko-first" name="first_name" required autocomplete="given-name" value="<?php echo esc_attr( $values['first_name'] ?? '' ); ?>"></p><p><label for="nekoko-last">Prezime *</label><input id="nekoko-last" name="last_name" required autocomplete="family-name" value="<?php echo esc_attr( $values['last_name'] ?? '' ); ?>"></p><p><label for="nekoko-email">Email *</label><input id="nekoko-email" type="email" name="email" required autocomplete="email" value="<?php echo esc_attr( $values['email'] ?? '' ); ?>"></p><p><label for="nekoko-password">Lozinka *</label><input id="nekoko-password" type="password" name="password" required minlength="10" autocomplete="new-password"></p><p><label for="nekoko-password-repeat">Ponovite lozinku *</label><input id="nekoko-password-repeat" type="password" name="password_repeat" required minlength="10" autocomplete="new-password"></p><p><label><input type="checkbox" name="terms" value="1" required> Prihvatam <a href="<?php echo esc_url( nekoko_core_page_url( 'pravila-koriscenja' ) ); ?>">uslove korišćenja</a> i <a href="<?php echo esc_url( get_privacy_policy_url() ); ?>">politiku privatnosti</a>.</label></p><p><button type="submit">Registrujte se</button></p></form>
